(() => {
 const host=$('#rail-view'),selected={from:null,to:null};let rows=[],total=0,searchVersion=0,searchController,loading=false,journeyVersion=0,active=null,scope='segment';
 const cache=new Map(),suggestions={};
 host.innerHTML=`<div class="metro-intro"><div class="metro-kicker">INDIAN RAILWAYS · SAVED TIMETABLES</div><h1 id="rail-heading">Your next rail journey.</h1><p>Find trains between stations, with every scheduled stop.</p></div><div class="bl-overview"><span><strong>14,300</strong> train records</span><span><strong>9,241</strong> stations</span></div><p class="bl-notice">eRail catalog collected 27 October 2026. Scheduled times in India (IST), not live departures. A listed train is not confirmation that it runs today. Confirm current schedules and operation with Indian Railways.</p>
 <form id="rail-form" class="metro-planner" novalidate><div class="rail-station-fields"><div class="rail-input-wrap"><label for="rail-from">From station</label><input id="rail-from" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="rail-from-options" placeholder="Station name or code" autocomplete="off" maxlength="80"><ul id="rail-from-options" class="rail-options" role="listbox" hidden aria-label="Departure railway stations"></ul></div><button id="rail-swap" class="icon-button swap" type="button" aria-label="Swap railway stations">${icon('swap')}</button><div class="rail-input-wrap"><label for="rail-to">To station</label><input id="rail-to" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="rail-to-options" placeholder="Station name or code" autocomplete="off" maxlength="80"><ul id="rail-to-options" class="rail-options" role="listbox" hidden aria-label="Destination railway stations"></ul></div></div><div class="rail-time"><label for="rail-after">Depart after (optional)</label><div><input type="time" id="rail-after"><button type="button" id="rail-any">Any time</button></div></div><button class="search-button" id="rail-search" type="submit">${icon('search')}<span>Search trains</span></button><p id="rail-error" class="form-error" role="alert" hidden></p></form>
 <div class="rail-results-heading"><h2>Trains on your route</h2><span id="rail-count" class="bl-badge bl-green">Choose stations</span></div><p id="rail-context" class="rail-muted"></p><p id="rail-status" class="rail-status" role="status" aria-live="polite">Choose two stations to search the railway catalog.</p><div id="rail-results"></div><button type="button" id="rail-more" class="metro-expand" hidden>Show more trains</button><button type="button" id="rail-retry" class="metro-expand" hidden>Retry search</button><div id="rail-empty" class="rail-empty"><span>${icon('metro')}</span><h3>Where will the rails take you?</h3><p>Search by station name or code, such as CAN or TLY.</p><button type="button" id="rail-popular" class="metro-expand">Try Kannur → Thalassery</button></div><p class="metro-source-note">Source: saved eRail lookup responses. Some source HTML pages disagree with these schedules. Fares, tickets, seat availability, cancellations and live running status are not provided here. Running weekdays refer to departure from the train’s origin, not necessarily your boarding station.</p>`;
 async function api(name,body,signal){const c=window.NERAM_RAIL_CONFIG;const response=await fetch(`${c.url}/rest/v1/rpc/${name}`,{method:'POST',headers:{apikey:c.publishableKey,'Content-Type':'application/json'},body:JSON.stringify(body),signal});if(!response.ok)throw new Error(`Railway request failed (${response.status})`);return response.json();}
 function invalidate(){searchVersion++;searchController?.abort();rows=[];total=0;loading=false;$('#rail-results').replaceChildren();$('#rail-count').textContent='Choose stations';$('#rail-context').textContent='';$('#rail-status').textContent='Choose stations and search to see matching trains.';$('#rail-more').hidden=true;$('#rail-retry').hidden=true;$('#rail-empty').hidden=false;$('#rail-search').disabled=false;$('#rail-search span').textContent='Search trains';$('#rail-error').hidden=true;}
 function setup(field){const input=$('#rail-'+field),list=$('#rail-'+field+'-options');let timer,controller,version=0,items=[],index=-1;
  function close(){list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');index=-1;}
  function choose(item){selected[field]=item;input.value=`${item.name} (${item.code})`;version++;controller?.abort();clearTimeout(timer);input.removeAttribute('aria-busy');close();invalidate();}
  function mark(){[...list.children].forEach((li,i)=>{li.setAttribute('aria-selected',String(i===index));li.classList.toggle('active',i===index);});if(index>=0){input.setAttribute('aria-activedescendant',list.children[index].id);list.children[index].scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');}
  async function load(){const q=input.value.trim();if(!q){close();return;}const v=++version;controller?.abort();controller=new AbortController();list.hidden=false;input.setAttribute('aria-expanded','true');input.setAttribute('aria-busy','true');items=[];index=-1;list.replaceChildren(textNode('li','Finding stations…','rail-option-note'));
   try{let found=cache.get(q.toLowerCase());if(!found){found=await api('neram_rail_stations',{p_query:q},controller.signal);if(cache.size>60)cache.delete(cache.keys().next().value);cache.set(q.toLowerCase(),found);}if(v!==version||document.activeElement!==input)return;items=found;list.replaceChildren();if(!items.length)list.append(textNode('li','No stations found. Try a station code.','rail-option-note'));
    items.forEach((item,i)=>{const li=document.createElement('li');li.id=`rail-${field}-option-${i}`;li.setAttribute('role','option');li.setAttribute('aria-selected','false');li.append(textNode('strong',`${item.name} · ${item.code}`),textNode('small',[item.district,item.state].filter(Boolean).join(', ')));li.addEventListener('mousedown',e=>e.preventDefault());li.addEventListener('click',()=>choose(item));list.append(li);});
   }catch(e){if(e.name!=='AbortError'&&v===version)list.replaceChildren(textNode('li','Could not load stations. Type again to retry.','rail-option-note'));}finally{if(v===version)input.removeAttribute('aria-busy');}
  }
  input.addEventListener('input',()=>{selected[field]=null;invalidate();clearTimeout(timer);version++;controller?.abort();close();timer=setTimeout(load,200);});input.addEventListener('focus',()=>{if(!selected[field])load();});
  input.addEventListener('keydown',e=>{if(e.key==='Escape'){version++;controller?.abort();close();return;}if(list.hidden)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(items.length){index=(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;mark();}}if(e.key==='Enter'&&index>=0){e.preventDefault();choose(items[index]);}});
  input.addEventListener('blur',()=>{clearTimeout(timer);version++;controller?.abort();close();input.removeAttribute('aria-busy');});suggestions[field]={close,choose};
 }
 setup('from');setup('to');
 function time(value){return value?timeLabel(value):'—';}
 function days(value){return value?value.split('|').join(' · '):'Not specified';}
 function elapsed(minutes){return minutes==null?'Duration unavailable':durationLabel(minutes);}
 function render(){const el=$('#rail-results');el.replaceChildren();rows.forEach(row=>{const button=document.createElement('button');button.type='button';button.className='rail-card';const head=document.createElement('div');head.className='rail-card-heading';const title=document.createElement('span');title.append(textNode('small',`TRAIN ${row.train_number}`),textNode('strong',row.train_name||'Unnamed train'));head.append(title,textNode('span','View route →','rail-view-link'));
  const route=document.createElement('div');route.className='rail-card-times';for(const [value,name,day] of [[row.departure_time,row.boarding_name,row.boarding_day],[row.arrival_time,row.alighting_name,row.alighting_day]]){const part=document.createElement('span');part.append(textNode('strong',time(value)),textNode('span',name),textNode('small',`Train day ${day||'—'}`));route.append(part);}const middle=textNode('span',elapsed(row.duration_minutes),'rail-duration');route.insertBefore(middle,route.lastChild);
  const foot=textNode('p',`Origin runs: ${days(row.operating_days)}`,'rail-card-days');button.append(head,route,foot);button.addEventListener('click',()=>openJourney(row));el.append(button);});$('#rail-count').textContent=`${total} catalog matches`;$('#rail-more').hidden=rows.length>=total||rows.length>=5000;$('#rail-empty').hidden=true;}
 async function search(more=false){if(loading)return;const from=selected.from,to=selected.to;if(!from||!to||from.code===to.code){$('#rail-error').hidden=false;$('#rail-error').textContent='Select two different stations from the suggestions.';return;}
  suggestions.from.close();suggestions.to.close();$('#rail-error').hidden=true;const after=$('#rail-after').value;const pAfter=after?Number(after.slice(0,2))*60+Number(after.slice(3)):null;const version=++searchVersion;searchController?.abort();searchController=new AbortController();loading=true;$('#rail-search').disabled=true;$('#rail-more').disabled=true;$('#rail-retry').hidden=true;$('#rail-search span').textContent='Finding trains…';$('#rail-status').textContent='Searching saved railway timetables…';$('#rail-empty').hidden=true;
  if(!more){rows=[];total=0;$('#rail-results').replaceChildren();$('#rail-count').textContent='Searching…';$('#rail-more').hidden=true;}
  try{const found=await api('neram_rail_search',{p_from:from.code,p_to:to.code,p_after:pAfter,p_offset:more?rows.length:0},searchController.signal);if(version!==searchVersion)return;total=found[0]?.total_results??(more?total:0);rows=more?[...rows,...found]:found;render();$('#rail-context').textContent=`${from.name} (${from.code}) → ${to.name} (${to.code})${after?' · Depart after '+time(after):''} · All origin running days`;
   $('#rail-status').textContent=total?`Showing ${rows.length} of ${total} catalog matches. Confirm operation for your travel date.`:'No matching train routes in this saved catalog. Try other stations or remove the time filter.';
  }catch(e){if(e.name!=='AbortError'&&version===searchVersion){$('#rail-status').textContent='Could not load railway timetables. Check your connection and retry.';$('#rail-retry').hidden=false;$('#rail-count').textContent=rows.length?`${rows.length} loaded`:'Unavailable';}}
  finally{if(version===searchVersion){loading=false;$('#rail-search').disabled=false;$('#rail-more').disabled=false;$('#rail-search span').textContent='Search trains';}}
 }
 $('#rail-form').addEventListener('submit',e=>{e.preventDefault();search();});$('#rail-more').addEventListener('click',()=>search(true));$('#rail-retry').addEventListener('click',()=>search(rows.length>0));
 $('#rail-swap').addEventListener('click',()=>{const from=selected.from;selected.from=selected.to;selected.to=from;for(const side of ['from','to']){const value=selected[side];$('#rail-'+side).value=value?`${value.name} (${value.code})`:'';suggestions[side].close();}invalidate();});$('#rail-after').addEventListener('change',invalidate);$('#rail-any').addEventListener('click',()=>{$('#rail-after').value='';invalidate();});
 $('#rail-popular').addEventListener('click',()=>{suggestions.from.choose({code:'CAN',name:'Kannur'});suggestions.to.choose({code:'TLY',name:'Thalassery'});search();});
 async function loadJourney(){const v=++journeyVersion,entry=active;$('#rail-journey-status').textContent='Loading route…';$('#rail-journey-retry').hidden=true;$('#rail-journey-stops').replaceChildren();try{entry.stops=await api('neram_rail_journey',{p_id:entry.row.train_id});if(v!==journeyVersion)return;renderJourney();}catch(e){if(v===journeyVersion){$('#rail-journey-status').textContent='Could not load this route. Please retry.';$('#rail-journey-retry').hidden=false;}}}
 function openJourney(row){active={row,stops:null};scope='segment';$('#rail-journey-title').textContent=`${row.train_number} · ${row.train_name||'Train'}`;$('#rail-journey-summary').textContent=`${row.boarding_name} → ${row.alighting_name} · ${elapsed(row.duration_minutes)}. Origin runs: ${days(row.operating_days)}.`;$('#rail-journey-dialog').showModal();loadJourney();}
 function renderJourney(){if(!active?.stops)return;const row=active.row,stops=scope==='full'?active.stops:active.stops.filter(s=>s.stop_order>=row.boarding_order&&s.stop_order<=row.alighting_order);$('#rail-segment').setAttribute('aria-pressed',String(scope==='segment'));$('#rail-full').setAttribute('aria-pressed',String(scope==='full'));$('#rail-journey-status').textContent=stops.length?`${stops.length} scheduled stops · train days count from origin departure.`:'No stop details available.';const el=$('#rail-journey-stops');el.replaceChildren();stops.forEach(stop=>{const li=document.createElement('li'),name=document.createElement('span');const board=stop.stop_order===row.boarding_order,alight=stop.stop_order===row.alighting_order;li.className=board?'rail-board':alight?'rail-alight':'';if(board||alight)name.append(textNode('small',board?'BOARD HERE':'GET OFF HERE','rail-stop-role'));name.append(textNode('strong',stop.station_name||stop.station_code),textNode('small',`${stop.station_code} · Train day ${stop.journey_day||'—'}`));const times=document.createElement('span');times.className='rail-stop-times';times.append(textNode('span',`Arr ${time(stop.arrival_time)}`),textNode('span',`Dep ${time(stop.departure_time)}`));li.append(name,times);el.append(li);});}
 $('#rail-segment').addEventListener('click',()=>{scope='segment';renderJourney();});$('#rail-full').addEventListener('click',()=>{scope='full';renderJourney();});$('#rail-journey-retry').addEventListener('click',loadJourney);
 window.addEventListener('neram:preferences',()=>{if(rows.length)render();if(active?.stops)renderJourney();});
})();
